Nat4	loadPersistents_MyCaseWindow(V_Environment environment);
Nat4	loadPersistents_MyCaseWindow(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("Tidy Offset H",tempPersistent_Tidy_20_Offset_20_H,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Tidy Offset V",tempPersistent_Tidy_20_Offset_20_V,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Tidy Grid H",tempPersistent_Tidy_20_Grid_20_H,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Tidy Grid V",tempPersistent_Tidy_20_Grid_20_V,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Minimum Size Text",tempPersistent_Minimum_20_Size_20_Text,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Case Dock Side",tempPersistent_Case_20_Dock_20_Side,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Auto Move Output Bar?",tempPersistent_Auto_20_Move_20_Output_20_Bar_3F_,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Case Window/Toolbar",NULL,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

Nat4	load_MyCaseWindow(V_Environment environment);
Nat4	load_MyCaseWindow(V_Environment environment)
{

	loadClasses_MyCaseWindow(environment);
	loadUniversals_MyCaseWindow(environment);
	loadPersistents_MyCaseWindow(environment);
	return kNOERROR;

}

